/*
 * This is the main workhorse for fork() and similar system calls.
 * It basically duplicates a process.
 */
pid_t do_fork(unsigned long clone_flags, unsigned long stack_ptr)
{
	struct task_struct *p;
	int clone_result;
	long ret;

	/*
	 * We're not allowing fork() to be called from interrupt context.
	 */
	if (in_interrupt())
		return -EINVAL;

	/* Check for valid clone flags */
	if (clone_flags & ~(CLONE_VM | CLONE_FS | CLONE_FILES | CLONE_SIGHAND |
			   CLONE_THREAD | CLONE_NEWUTS | CLONE_NEWPID |
			   CLONE_NEWNET | CLONE_NEWNS | CLONE_NEWIPC |
			   CLONE_PARENT | CLONE_PARENT_SETTID | CLONE_CHILD_CLEARTID |
			   CLONE_CHILD_SETTID))
		return -EINVAL;

	/*
	 * Allocate the new task structure.  This is the main structure
	 * describing the process.
	 */
	p = dup_task_struct(current);
	if (!p)
		return -ENOMEM;

	/*
	 * Copy the process state.
	 */
	ret = copy_process(p, clone_flags);
	if (ret < 0) {
		/* The copy_process() function will already have freed the
		 * partially completed task structure. */
		return ret;
	}

	/*
	 * If the caller wants a new PID namespace, create it now.
	 */
	if (clone_flags & CLONE_NEWPID) {
		ret = pid_namespace_create(p);
		if (ret < 0) {
			/* copy_process already allocated resources. Clean them up. */
			deallocate_task_struct(p);
			return ret;
		}
	}

	/*
	 * If the caller wants a new network namespace, create it now.
	 */
	if (clone_flags & CLONE_NEWNET) {
		ret = net_namespace_create(p);
		if (ret < 0) {
			/* cleanup pid namespace if created */
			if (clone_flags & CLONE_NEWPID)
				pid_namespace_release(p->nsproxy->pid_ns);

			deallocate_task_struct(p);
			return ret;
		}
	}

	/*
	 * If the caller wants a new mount namespace, create it now.
	 */
	if (clone_flags & CLONE_NEWNS) {
		ret = mnt_namespace_create(p);
		if (ret < 0) {
			/* cleanup net namespace if created */
			if (clone_flags & CLONE_NEWNET)
				net_namespace_release(p->nsproxy->net_ns);
			/* cleanup pid namespace if created */
			if (clone_flags & CLONE_NEWPID)
				pid_namespace_release(p->nsproxy->pid_ns);
			deallocate_task_struct(p);
			return ret;
		}
	}

	/*
	 * If the caller wants a new IPC namespace, create it now.
	 */
	if (clone_flags & CLONE_NEWIPC) {
		ret = ipc_namespace_create(p);
		if (ret < 0) {
			/* cleanup mnt namespace if created */
			if (clone_flags & CLONE_NEWNS)
				mnt_namespace_release(p->nsproxy->mnt_ns);
			/* cleanup net namespace if created */
			if (clone_flags & CLONE_NEWNET)
				net_namespace_release(p->nsproxy->net_ns);
			/* cleanup pid namespace if created */
			if (clone_flags & CLONE_NEWPID)
				pid_namespace_release(p->nsproxy->pid_ns);
			deallocate_task_struct(p);
			return ret;
		}
	}

	/*
	 * If the caller wants a new UTS namespace, create it now.
	 */
	if (clone_flags & CLONE_NEWUTS) {
		ret = uts_namespace_create(p);
		if (ret < 0) {
			/* cleanup ipc namespace if created */
			if (clone_flags & CLONE_NEWIPC)
				ipc_namespace_release(p->nsproxy->ipc_ns);
			/* cleanup mnt namespace if created */
			if (clone_flags & CLONE_NEWNS)
				mnt_namespace_release(p->nsproxy->mnt_ns);
			/* cleanup net namespace if created */
			if (clone_flags & CLONE_NEWNET)
				net_namespace_release(p->nsproxy->net_ns);
			/* cleanup pid namespace if created */
			if (clone_flags & CLONE_NEWPID)
				pid_namespace_release(p->nsproxy->pid_ns);
			deallocate_task_struct(p);
			return ret;
		}
	}

	/*
	 * Initialize the new process's credentials.
	 */
	prepare_creds(p);

	/*
	 * Start the new process.
	 */
	clone_result = kernel_thread(finish_task, p, stack_ptr);
	if (clone_result < 0) {
		/* cleanup UTS namespace if created */
		if (clone_flags & CLONE_NEWUTS)
			uts_namespace_release(p->nsproxy->uts_ns);
		/* cleanup ipc namespace if created */
		if (clone_flags & CLONE_NEWIPC)
			ipc_namespace_release(p->nsproxy->ipc_ns);
		/* cleanup mnt namespace if created */
		if (clone_flags & CLONE_NEWNS)
			mnt_namespace_release(p->nsproxy->mnt_ns);
		/* cleanup net namespace if created */
		if (clone_flags & CLONE_NEWNET)
			net_namespace_release(p->nsproxy->net_ns);
		/* cleanup pid namespace if created */
		if (clone_flags & CLONE_NEWPID)
			pid_namespace_release(p->nsproxy->pid_ns);
		deallocate_task_struct(p);
		return clone_result;
	}

	return p->pid;
}
